CREATE OR REPLACE FUNCTION public.my_confirmed_usual_provider() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE source_id uuid; target_id uuid; result jsonb; BEGIN
SELECT CASE WHEN count(*)=1 THEN min(m.workspace_id::text)::uuid END INTO source_id FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.user_id=auth.uid() AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.account_type IN ('private_pay','facility','hospital') AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL;
IF source_id IS NULL THEN RETURN NULL; END IF;
SELECT preferred_provider_id INTO target_id FROM public.account_relationship_preferences WHERE workspace_id=source_id;
IF target_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.account_business_connections c WHERE c.active AND c.workspace_a=least(source_id,target_id) AND c.workspace_b=greatest(source_id,target_id)) THEN RETURN NULL; END IF;
SELECT jsonb_build_object('workspace_id',w.id,'business_name',w.display_name,'mfn_id',w.mfn_id,'description',n.description,'business_contact_email',CASE WHEN n.contact_email_public THEN n.business_contact_email END,'business_contact_phone',CASE WHEN n.contact_phone_public THEN n.business_contact_phone END,'service_types',coalesce(n.service_types,'{}'::text[]),'counties',coalesce(n.counties,'{}'::text[]),'cities',coalesce(n.cities,'{}'::text[]),'zips','[]'::jsonb,'hours',n.hours,'medical_delivery',coalesce(n.medical_delivery,false),'accepting_connections',coalesce(n.accepting_connections,false),'is_saved',true) INTO result FROM public.workspaces w LEFT JOIN public.provider_network_profiles n ON n.workspace_id=w.id WHERE w.id=target_id AND w.account_type='provider' AND w.status='active' AND NOT w.is_test_account AND EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=w.id AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL);
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.my_confirmed_usual_provider() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.my_confirmed_usual_provider() TO authenticated;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='search_business_identities'; IF definition IS NULL THEN RAISE EXCEPTION 'Existing identity projection missing'; END IF; definition:=replace(definition,'THEN w.automatic_verification_level ELSE NULL END','THEN w.automatic_verification_level WHEN w.account_type IN (''facility'',''hospital'') AND public.account_profile_evidence(w.id)->>''status''=''verified'' THEN ''verified'' ELSE NULL END'); EXECUTE definition; END $$;